	@Test
	void repositorySnapshotsReusedMutableBindingSetsAndKeepsRecursiveValuesStable(@TempDir File directory)
			throws Exception {
		try (ObservedValues store = new ObservedValues(directory)) {
			var valueFactory = SimpleValueFactory.getInstance();
			TripleTerm firstNested = valueFactory.createTripleTerm(
					valueFactory.createIRI("http://example.org/firstSubject"),
					valueFactory.createIRI("http://example.org/predicate"),
					valueFactory.createLiteral("first nested", valueFactory.createIRI("http://example.org/datatype")));
			TripleTerm secondNested = valueFactory.createTripleTerm(
					valueFactory.createIRI("http://example.org/secondSubject"),
					valueFactory.createIRI("http://example.org/predicate"),
					valueFactory.createLiteral("second nested", valueFactory.createIRI("http://example.org/datatype")));
			MapBindingSet reused = new MapBindingSet();
			reused.addBinding("value", firstNested);
			AtomicInteger pulls = new AtomicInteger();
			AtomicInteger closes = new AtomicInteger();
			var source = new IterationWrapper<BindingSet>(
					new CloseableIteratorIteration<>(List.of(reused, reused).iterator())) {
				@Override
				public BindingSet next() {
					int row = pulls.getAndIncrement();
					reused.setBinding("value", row == 0 ? firstNested : secondNested);
					return super.next();
				}

				@Override
				protected void handleClose() {
					closes.incrementAndGet();
					super.handleClose();
				}
			};
			try (var result = new RepositoryValueIteration<>(source, SailResultValueExtractor.BINDING_SETS, store, null,
					ignored -> {
					})) {
				BindingSet first = result.next();
				assertNotSame(reused, first, "Mutable generic rows require a per-request shallow copy");
				assertSame(firstNested, first.getValue("value"));
				assertEquals(1, pulls.get(), "Preparing the first value must not prefetch the next row");

				BindingSet second = result.next();
				assertNotSame(first, second, "Each reused source row needs its own immutable current snapshot");
				assertSame(secondNested, second.getValue("value"));
				assertSame(firstNested, first.getValue("value"),
						"Source mutation must not replace recursively reachable values in the prior snapshot");
				assertEquals(2, pulls.get());
				result.close();
				assertEquals(1, closes.get(), "Early result close must close the mutable source once");
			}
		}
	}

	@Test
	void sourceClosingDuringNextCannotReleaseTheRowsOlderEpoch(@TempDir File directory) throws Exception {
		try (ObservedValues store = new ObservedValues(directory)) {
			ValueResolutionScope creator = store.openValueResolutionScope();
			List<Value> values = seed(store, creator, 2);
			ValueStoreRevision.Lazy earlier = (ValueStoreRevision.Lazy) ((LmdbValue) values.getFirst())
					.getValueStoreRevision();
			rotate(store, creator);
			var source = new IterationWrapper<List<Value>>(
					new CloseableIteratorIteration<>(List.of(values).iterator())) {
				@Override
				public List<Value> next() {
					List<Value> row = super.next();
					close();
					return row;
				}

				@Override
				protected void handleClose() {
					try {
						super.handleClose();
					} finally {
						creator.close();
					}
				}
			};
			try (var result = exposeRoots(store, source, null)) {
				assertSame(values, result.next());
				assertFalse(creator.isOpen(), "The source next must really close its inner owner before preparation");
				assertTrue(isEpochProtected(store, earlier),
						"The outward owner retains the original horizon");
				for (Value value : values) {
					assertInstanceOf(ValueStoreRevision.Default.class, ((LmdbValue) value).getValueStoreRevision());
				}
				assertFalse(result.hasNext());
				assertFalse(isEpochProtected(store, earlier),
						"Observed exhaustion releases the outward owner's horizon");
			}
		}
	}

	@Test
	void multipleResultsBorrowTheTransactionReaderAndBufferedRowsSurviveItsCompletion(@TempDir File directory)
			throws Exception {
		try (ObservedValues store = new ObservedValues(directory);
				ValueResolutionScope transaction = store.openValueResolutionScope()) {
			List<Value> values = seed(store, transaction, 4);
			List<Value> firstRow = values.subList(0, 2);
			List<Value> secondRow = values.subList(2, 4);
			try (var first = exposeRoots(store, new CloseableIteratorIteration<>(List.of(firstRow).iterator()),
					transaction);
					var second = exposeRoots(store, new CloseableIteratorIteration<>(List.of(secondRow).iterator()),
							transaction)) {
				assertTrue(first.hasNext());
				assertTrue(second.hasNext());
				assertEquals(1, store.admissions.get(),
						"Two results in one transaction must share its foreground reader");
				rotate(store, transaction);
				transaction.close();
				assertTrue(store.readers.stream().allMatch(reader -> reader.isIdle() || reader.isClosed()));
				assertSame(firstRow, first.next());
				assertSame(secondRow, second.next());
				assertFalse(first.hasNext());
				assertFalse(second.hasNext());
				assertEquals(1, store.admissions.get(),
						"Already ready buffered rows need no post-commit native reader");
			}
		}
	}

